VALUES ('cao-r8', '兕', ARRAY[]::text[], '姬', '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '曹国第九代君主，惠伯。在位三十余年，国力平平，无显著事迹，维持小国，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹惠伯"}]'::jsonb, '惠伯', NULL, '曹惠伯')
