VALUES ('cao-r9', '石甫', ARRAY[]::text[], '姬', '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '惠伯之子，在位仅一年即被废。曹国政局一度动荡，旋即传位穆公，国势不稳，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹废伯"}]'::jsonb, '废伯', NULL, '曹废伯')
