VALUES ('cao-r10', '武', ARRAY[]::text[], '姬', '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '废伯之弟，在位三年。旋即传位桓公，曹国政局渐趋稳定，国势略有回升，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹穆公"}]'::jsonb, '穆公', NULL, '曹穆公')
