VALUES ('cao-r11', '终生', ARRAY[]::text[], '姬', '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '曹桓公（姬终生），《史记·蔡世家》载前756–前702年在位，共55年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹桓公"}]'::jsonb, '桓公', NULL, '曹桓公')
