VALUES ('cao-r12', '夕姑', ARRAY[]::text[], '姬', '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位三十年，曹国尚存一定影响力。春秋中期君主，国势尚可，无力争霸，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹庄公"}]'::jsonb, '庄公', NULL, '曹庄公')
