VALUES ('cao-r13', '夷', ARRAY[]::text[], '姬', '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '庄公之子，在位八年。曹国已渐趋式微，无力外争，仰息于晋楚等强邻，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹釐公"}]'::jsonb, '釐公', NULL, '曹釐公')
