VALUES ('cao-r15', '襄', ARRAY[]::text[], '姬', '曹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '以刻薄闻名，《左传》载晋公子重耳过曹曾受冷遇。在位三十余年，国势日衰，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹共公"}]'::jsonb, '共公', NULL, '曹共公')
